// Matriz de decisión. Los puntajes (1 a 5) son OPINIÓN del autor, no una medición.
const criterios = ['modelo de datos', 'consistencia', 'operación', 'equipo', 'costo', 'escala', 'latencia', 'ecosistema'];
const puntajes = {
  'PostgreSQL': [5, 5, 4, 4, 4, 4, 3, 5],
  'SQLite':     [4, 4, 5, 4, 5, 2, 4, 3],
  'MongoDB':    [3, 4, 4, 2, 3, 5, 3, 4],
  'Redis':      [1, 2, 3, 3, 3, 5, 5, 4],
};
// Dos casos inventados, mismos candidatos, distintos pesos (0 a 3):
const casos = {
  'A) seguimiento de bultos (200.000 por mes)': [3, 3, 2, 2, 1, 1, 1, 1],
  'B) puesto de cada persona en un ranking de un millón': [0, 1, 2, 2, 1, 3, 3, 1],
};
const total = (pesos, pts) => pts.reduce((s, p, i) => s + p * pesos[i], 0);
const ranking = (pesos) => Object.entries(puntajes).map(([n, pts]) => [n, total(pesos, pts)]).sort((a, b) => b[1] - a[1]);

for (const [caso, pesos] of Object.entries(casos)) {
  console.log(caso);
  console.log('  pesos:', criterios.map((c, i) => `${c} ${pesos[i]}`).join(', '));
  for (const [n, t] of ranking(pesos)) console.log('  ' + n.padEnd(11), String(t).padStart(3));
}

// ¿Cuánto tendría que pesar "escala" en el caso A para que Postgres deje de ganar?
const A = casos['A) seguimiento de bultos (200.000 por mes)'].slice();
let w = A[5];
while (ranking(A.map((v, i) => (i === 5 ? w : v)))[0][0] === 'PostgreSQL' && w < 100) w++;
const otros = A.reduce((s, v, i) => (i === 5 ? s : s + v), 0);
console.log(`\nCaso A: Postgres pierde el primer puesto cuando "escala" pesa ${w} (hoy pesa 1; todos los demás criterios suman ${otros}).`);
